  const isBlocked = opts.isBlocked || blockedCallback(buildBlocksVisionMap(world));
  const canSee = hasOverworldAerialLOS(world, {
    sourceId: actor,
    targetId: target,
    sourcePos: actorPos,
    targetPos,
    range,
  }) || hasLOS(actorPos.x | 0, actorPos.y | 0, targetPos.x | 0, targetPos.y | 0, isBlocked);
